import React, { useState, useMemo } from "react";
import MatchItem from "./MatchItem";

function MatchList({ matches, selectedLeague, orderedLeagues }) {
  // Состояние для выбранной даты (по умолчанию сегодня)
  const [selectedDate, setSelectedDate] = useState(
    new Date().toISOString().split("T")[0],
  );

  // Генерация списка дат (Вчера + Сегодня + 7 дней вперед)
  const dateOptions = useMemo(() => {
    const dates = [];
    for (let i = -1; i <= 7; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      dates.push({
        full: d.toISOString().split("T")[0],
        day: d.getDate(),
        weekday: d.toLocaleDateString("ru-RU", { weekday: "short" }),
        isToday: i === 0,
      });
    }
    return dates;
  }, []);

  // Фильтрация матчей по выбранной дате
  const filteredByDate = matches.filter(
    (m) => m.utcDate.split("T")[0] === selectedDate,
  );

  // Группировка отфильтрованных матчей по лигам
  const groupedMatches = useMemo(() => {
    const groups = {};
    filteredByDate.forEach((match) => {
      const leagueCode = match.league;
      if (!groups[leagueCode]) {
        const leagueObj = orderedLeagues.find(
          (l) => l.code === leagueCode || l.name === leagueCode,
        );
        groups[leagueCode] = {
          name: leagueObj ? leagueObj.name : leagueCode,
          matches: [],
        };
      }
      groups[leagueCode].matches.push(match);
    });
    return groups;
  }, [filteredByDate, orderedLeagues]);

  if (!matches || matches.length === 0) {
    return (
      <p className="text-center text-gray-500 py-10 font-bold uppercase tracking-widest">
        Загрузка данных...
      </p>
    );
  }

  return (
    <div className="w-full">
      {/* 1. ПАНЕЛЬ НАВИГАЦИИ ПО ДАТАМ */}
      <div className="flex items-center gap-2 mb-8 bg-gray-900/50 p-2 rounded-2xl border border-gray-800 overflow-x-auto no-scrollbar">
        {/* Кнопка Календаря */}
        <div className="relative flex-shrink-0">
          <input
            type="date"
            className="absolute inset-0 opacity-0 cursor-pointer z-10"
            onChange={(e) => setSelectedDate(e.target.value)}
          />
          <button className="w-12 h-12 flex items-center justify-center bg-gray-800 rounded-xl hover:bg-red-600 transition-colors">
            <svg
              className="w-5 h-5 text-white"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
              />
            </svg>
          </button>
        </div>

        {/* Быстрые даты */}
        <div className="flex gap-2">
          {dateOptions.map((d) => (
            <button
              key={d.full}
              onClick={() => setSelectedDate(d.full)}
              className={`flex flex-col items-center justify-center min-w-[56px] h-12 rounded-xl transition-all ${
                selectedDate === d.full
                  ? "bg-red-600 text-white shadow-lg shadow-red-600/20"
                  : "bg-gray-800 text-gray-500 hover:bg-gray-700"
              }`}
            >
              <span className="text-[10px] font-black uppercase leading-none mb-1">
                {d.weekday}
              </span>
              <span className="text-sm font-black leading-none">{d.day}</span>
            </button>
          ))}
        </div>
      </div>

      {/* 2. ВЫВОД МАТЧЕЙ */}
      {Object.keys(groupedMatches).length === 0 ? (
        <div className="text-center py-20 bg-gray-900/30 rounded-3xl border border-dashed border-gray-800">
          <p className="text-gray-600 font-black uppercase tracking-widest text-sm">
            Матчей на {selectedDate} не найдено
          </p>
        </div>
      ) : (
        Object.entries(groupedMatches).map(([code, league]) => (
          <div key={code} className="mb-12">
            {/* Заголовок Лиги + Тур (если есть) */}
            <div className="flex flex-col items-center mb-6">
              <h2 className="text-xl md:text-2xl font-black text-white uppercase tracking-tighter">
                {league.name}
              </h2>
              {/* Предполагаем, что matchday есть в данных матча (мы его сохраняли в парсере) */}
              <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.3em] mt-1">
                Matchday{" "}
                {league.matches[0].matchday || league.matches[0].season}
              </span>
              <div className="w-16 h-1 bg-red-600 mt-2 rounded-full opacity-50"></div>
            </div>

            {/* Сетка матчей: 1 колонка мобилки, 2 планшет, 3 десктоп */}
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 md:gap-6">
              {league.matches.map((match) => (
                <MatchItem key={match.id} match={match} />
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

export default MatchList;
